import{_ as t}from"./chunks/home.pc.en.BIVUBvtu.js";import{_ as o}from"./chunks/home-estop.pc.en.BSpMx1St.js";import{_ as n,o as a,c as s,a5 as r}from"./chunks/framework.BYXPg_yw.js";const w=JSON.parse('{"title":"Control home","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/control-home.md","filePath":"manual/gui/control-home.md","lastUpdated":1793350928000}'),i={name:"manual/gui/control-home.md"};function d(h,e,c,l,g,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="control-home" tabindex="-1">Control home <a class="header-anchor" href="#control-home" aria-label="Permalink to &quot;Control home&quot;">​</a></h1><p>The control home is the screen you drive the robot from. Open it with <strong>Control</strong> on the Hub. The whole screen is the viewport — a camera feed or the 3D view — with a motion card on the left, an <strong>OBSERVE</strong> card on the right, and two virtual joysticks in the lower corners when no gamepad is connected.</p><p><img src="'+t+'" alt="Control home"></p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Every motion button on this screen moves the real robot. <strong>Keep people, animals, and obstacles at least 2 m clear of the robot whenever it is operating.</strong> Check your surroundings before you press anything, and keep a hand near <code>E-STOP</code>.</p></div><h2 id="top-bar" tabindex="-1">Top bar <a class="header-anchor" href="#top-bar" aria-label="Permalink to &quot;Top bar&quot;">​</a></h2><p>The top bar floats over the video in two groups. From left to right:</p><table tabindex="0"><thead><tr><th>Element</th><th>What it shows / does</th></tr></thead><tbody><tr><td>Logo</td><td>Opens the screen menu — <strong>Hub</strong>, <code>Control</code>, <code>Dashboard</code>, <code>Settings</code>, <code>Maintenance</code>, <code>Logs</code>, <code>Media</code>, <code>Guide</code>, <code>Update</code>. Leaving the control screen stops the robot where it is; it stays connected</td></tr><tr><td>Status light</td><td>A green, amber, or red light that pulses slowly — fast when something is critical, and a steady red while not connected. Tap it for <strong>Overall system status</strong> (see <a href="/RBQ/nightly/manual/gui/connection.html#connection-status-in-the-top-bar">Connection</a>)</td></tr><tr><td>Gait chip</td><td>The robot&#39;s current gait name, such as <code>STANDING</code>, colored by state. Hidden while not connected</td></tr><tr><td><code>SLAM</code> chip</td><td>Appears only while external control (SLAM or SDK) is active. Tap it to hand control back to the app</td></tr><tr><td>Signal bars</td><td>WiFi signal strength, and how fast data is moving over the robot link</td></tr><tr><td>Log badge</td><td>Unread log alerts</td></tr><tr><td><strong>Robot</strong> battery, device battery</td><td>The robot pack&#39;s charge, with a charging mark while it charges, and your own device&#39;s battery. Tap the robot battery for <strong>Battery details</strong> — voltage, time to 80% on CAN-FD robots, and charging warnings</td></tr><tr><td><code>E-STOP</code></td><td>Emergency stop — see below</td></tr><tr><td>Quit</td><td>Desktop build only. Asks <strong>Quit the app?</strong> first, then closes the app. The robot keeps running</td></tr></tbody></table><p>If the robot drops off and does not come back within 8 seconds, the app takes you to the Hub on its own, because that is where you reconnect. It also goes back to the Hub the moment the connected robot changes, so you never end up driving a robot you did not pick.</p><p>Going back (the Android back button, or <code>Esc</code> on a PC or Steam Deck) takes you from this screen to the <strong>Hub</strong>, the same as <strong>Hub</strong> in the logo menu. The gamepad <code>B</code> button is a robot button on this screen, so it does not leave it. On a PC or Steam Deck, <code>B</code> goes back on screens that don&#39;t use it as a robot button. Going back from the Hub asks <strong>Quit the app?</strong> first (Android and desktop).</p><h3 id="e-stop" tabindex="-1">E-STOP <a class="header-anchor" href="#e-stop" aria-label="Permalink to &quot;E-STOP&quot;">​</a></h3><p><code>E-STOP</code> never fires on a single tap. Pressing it opens the confirmation <strong>Emergency stop?</strong>, which warns that <em>The robot immediately stops all motion and cuts power. Reinitialization is required to resume control.</em> Press <strong>Stop</strong> to go ahead or <strong>Cancel</strong> to back out. The button behaves the same way on every screen, even with a menu open.</p><p><img src="'+o+'" alt="E-STOP confirmation"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>After an emergency stop the robot has no motor power. Bring it back with <strong>Auto Start</strong> (below) before it can move again. The step chips show you where the sequence stopped.</p></div><h3 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h3><p>Only one device controls the robot at a time. When another device holds control, the status light turns amber and the <strong>Ownership</strong> row in <strong>Overall system status</strong> reads <code>Take ▸</code> — tap it to take control back. While a SLAM or SDK program is driving, you get the <code>SLAM</code> chip instead.</p><p>While another device holds control, this device spectates: the screen stays visible, the controls below the top bar are locked, and <code>Spectating</code> at the top offers to take control. See <a href="/RBQ/nightly/manual/gui/emergency.html#spectating">Spectating</a>.</p><h2 id="auto-start" tabindex="-1">Auto Start <a class="header-anchor" href="#auto-start" aria-label="Permalink to &quot;Auto Start&quot;">​</a></h2><p>Until the robot&#39;s motor control is running, a green <strong>Auto Start</strong> pill sits at the bottom center of the viewport, grayed out while not connected. Tap it to open the <strong>Auto Start</strong> dialog. The dialog always stays centered on the screen: when the screen is short, only the <strong>Startup sequence</strong> list inside it scrolls and the buttons stay visible. On a short screen such as a phone in landscape, each step shows as one line — tap it to open or close its details. The running step and any failed or warning step open by themselves.</p><ol><li>Read the instruction — <em>Place the robot on a flat floor, and make sure all feet and knees contact the ground.</em></li><li>Five step chips lay out the sequence: <strong>POWER</strong>, <strong>CAN-BUS</strong>, <strong>HOMING</strong>, <strong>IMU-CHECK</strong>, <strong>START</strong>. Tap an unfinished <strong>CAN-BUS</strong> or <strong>HOMING</strong> chip to run just that step.</li><li>Press <strong>Auto Start</strong>. The dialog stays open and the <strong>Startup sequence</strong> panel below the chips fills in step by step — Pre-check, Leg Power, Data rate, Joint comms, Motor parameters, Home position, IMU, Control active — marking each one <strong>Passed / Failed / Warning / Running</strong>.</li><li>If a step fails, the panel names the cause and the fix. For example: <em>The robot is already standing — Sit the robot down, then start again.</em> Take care of it and press <strong>Start again</strong>.</li><li>Press <strong>Close</strong> once the sequence reports <strong>Done</strong>. When a run you watched here clears the last step, <strong>Start again</strong> disappears and only <strong>Close</strong> remains, so you cannot start the sequence twice by accident.</li></ol><p>You can also start the same sequence from the status light: <strong>Overall system status › ▶ Auto start (full sequence)</strong>.</p><h2 id="viewport-and-source-selector" tabindex="-1">Viewport and source selector <a class="header-anchor" href="#viewport-and-source-selector" aria-label="Permalink to &quot;Viewport and source selector&quot;">​</a></h2><p>The dropdown at the top center of the viewport picks what you see. <code>3D</code>, a live model of the robot, is always there. Camera sources show up only when the robot reports having that camera: <strong>Front</strong>, <strong>Rear</strong>, <strong>Left</strong>, <strong>Right</strong>, <strong>Stairs</strong>, <strong>Quad</strong>, <strong>Panorama</strong>, <code>CCTV</code>, <strong>Thermal</strong>, <strong>PTZ Mix</strong>, and <code>SLAM</code> on LiDAR robots. Tap outside the list to close it without changing the source.</p><p>On CAN-FD robots, when the <a href="/RBQ/nightly/manual/gui/maintenance.html#led-bottom">bottom status LEDs</a> are on, the 3D view in <code>3D</code> and <strong>Stairs</strong> shows the same colored light. It lights the LED spots under the body, the legs and the floor at foot level, and a blinking LED blinks at the same pace. Each LED casts its own circle on the floor; the two circles overlap slightly off-center, and where they overlap the colors mix. The floor light shrinks as the body lowers. It is not drawn while LiDAR or heightmap points or the obstacle map are shown, so they do not overlap.</p><p>Pick a PTZ-type source and the pan/tilt/zoom panel appears over the video. Drag it by its handle to move it.</p><p>While docking runs, the selector reads <code>Dock</code> and will not open — the viewport belongs to <a href="/RBQ/nightly/manual/gui/camera-vision.html#dock-view">Dock View</a> until you close it.</p><h2 id="left-card-—-motion" tabindex="-1">Left card — Motion <a class="header-anchor" href="#left-card-—-motion" aria-label="Permalink to &quot;Left card — Motion&quot;">​</a></h2><p>Everything that makes the robot move lives on the left.</p><ul><li><strong>Card</strong>: folded, it is a round glass button with a walking-person icon. Tap it and the circle grows into the card; tap the card&#39;s top row to fold it back. The app remembers whether each card is open, and both start open.</li><li><strong>Body</strong>: the fixed motion buttons <code>SIT</code>, <code>STAND</code>, <code>WALK</code>, <code>STAIRS</code>, and <code>DOCKING</code> (only while docking is available), plus <strong>Motion</strong>, the dashed button that opens the full motion grid. Whichever button matches the robot&#39;s current gait is highlighted. See <a href="/RBQ/nightly/manual/gui/motion-commands.html">Motion commands</a>.</li><li><strong>Tool buttons</strong>: a row of small buttons outside the card, just right of the left joystick — at the left edge in gamepad mode. Each one opens its panel above the row: <ul><li><strong>Drive</strong> — speed, body height, and tilt sliders (<a href="/RBQ/nightly/manual/gui/motion-commands.html#drive-parameters">Drive parameters</a>).</li><li><strong>Arm</strong> — only on robots with a manipulator.</li><li><strong>Input</strong> — the input mode <strong>Auto / Virtual / Pad</strong> and the live gamepad map. <em>Auto</em> switches to a physical gamepad whenever one is connected. A green dot means external control is doing the driving.</li></ul></li><li>When the card is taller than the screen, a <code>▾</code> at the bottom tells you it scrolls.</li></ul><p>Arm operation controls are shown only when the arm 48V rail is on and all six arm joints communicate. Turning arm power off hides these controls. Manual inputs are canceled on power loss. You can leave the manual workspace without requesting Folding; after power returns, start manual control again explicitly. Simulation has no power distribution unit, so the power condition is not applied there.</p><p>The <code>Arm</code> menu holds two screens, <code>Manual control</code> and <code>Arm motions</code>, and four basic poses: <code>Folding</code>, <code>Ready</code>, <code>Straight</code> and <code>Lift</code>. The poses move the arm from the menu itself without opening a screen, and are available only while arm control is started and the arm position lock is released.</p><p>Choose <code>Arm</code> → <code>Arm motions</code> to open the motion list and the live robot-and-arm 3D view. The list contains <code>Greeting</code>, <code>Multi joint</code>, <code>Auto Recovery</code> and <code>Damping Mode</code>.</p><p>The robot rejects a motion when the first one is not the ready pose. Until you press <code>Ready pose</code> once after entering the screen, the other motions appear disabled and a notice is shown. Leaving and re-entering the screen requires pressing it again. Demo motions swing the arm widely, so clear the area before running them.</p><p>Choose <code>Arm</code> → <code>Manual control</code> to open the body-front camera beside one combined robot-and-arm 3D control view. The gripper is highlighted in amber. <code>EE focus</code> follows the measured arm tip at a close distance, with a live full-robot 3D PIP in the upper right. Tap that PIP or <code>Full view</code> to see the whole robot; <code>EE focus</code> returns to the close view. Both views use the same measured robot model. EE coordinate axes use the selected control frame and scale with the view size and zoom. Arrows and touch targets are wider, and the default length is 140% of the previous size. Open <code>Input feedback</code> in the 3D header and use its <code>Axis size</code> slider or <code>Smaller axes</code> / <code>Larger axes</code> to choose 100–200%; <code>Defaults</code> restores 140%. This device remembers the setting. Axis size is limited near view edges to prevent clipping. Opening the setting stops current input; changing the display size does not change jog speed or the control frame. The same setting lets you compare A (axis glow), B (a tether from the grab point to your finger), C (a direction ribbon), and B+C (tether and ribbon). This device remembers the choice. Grabbing an axis shows it as held; dragging beyond the small screen dead zone shows the +/− input direction. Rotation uses a curved indicator, or the existing up/down gesture direction when the axis cannot be resolved in the current view. Releasing or canceling input removes the indicator. These graphics show user input, not confirmed robot motion, physical stopping, travel distance, speed or force. The hand camera remains in its own bottom-right PIP within the front video; both camera images use one composed stream.</p><p>On narrow screens the camera sits above the combined 3D view. Controls stay in a fixed bottom bar, with larger −/+ and gripper touch targets. <code>Button controls</code> and <code>Axis drag</code> do not resize or remount the views. On web and desktop, holding a jog button keeps the input pressed even if the finger slides outside its bounds; lifting, touch cancellation, lost pointer capture, a second touch, focus loss or disabling the control cancels the hold. Space/Enter can hold a focused button; releasing the key stops it. Routine captions are omitted, while connection, power, error and missing-pose/frame states remain visible. <code>Enlarge 3D</code> swaps camera and 3D panel sizes; <code>Enlarge camera</code> restores them. On wide screens the divider resizes those columns and supports the left/right arrow keys. Changing views or resizing cancels held input.</p><p>Opening this screen does not move the arm. Press <code>Start manual control</code> to request manual control, which may move the arm to its ready pose. The EE and gripper controls become available when the robot reports manual control. Grab an arrow at the highlighted gripper in the combined 3D view and drag along its axis. In <code>Rotate</code>, grab the selected curved arrow and drag around the arc. The model follows orientation calculated from measured joints and body attitude; RBA-1 fingers also follow measured opening. EE focus follows the measured arm-tip position, and missing pose data shows a waiting message. Clicking or grabbing alone does not move the arm. Moving beyond a small screen dead zone jogs at the existing speed while the pointer remains displaced from the grab point. Returning to the grab point, releasing or canceling the touch requests input stop. Drag distance does not specify travel distance or a target pose. The gesture frame freezes at grab time, so live model motion cannot change its direction. Reversing waits for the stop request to be accepted before starting the other direction. An axis that is difficult to resolve in the current view uses upward drag for + and downward drag for −. X/Roll is red, Y/Pitch green and Z/Yaw blue. The curved arrow indicates positive rotation. Dragging a selected EE handle controls the arm; dragging elsewhere in the 3D view rotates the viewpoint. The full-robot PIP only switches the view and never sends movement. In FC frame, movement arrows at the EE show the controller&#39;s level foot-center frame, including its foot-twist correction; in EE frame, movement arrows and rotation axes follow the local arm-tip frame. FC display requires updated ManiControl and Network on the robot. If FC telemetry is missing, the drag model shows a waiting message rather than body-aligned axes; existing button controls remain available. Existing axis and <code>−</code>/<code>+</code> buttons are available in the <code>Button controls</code> tab. <code>Stop EE input</code> stays visible. Changing axes or modes, switching input tabs, a second touch, leaving the screen or hiding the app cancels current input and pending drag starts. Gripper open and close remain separate hold controls. <code>Fix</code> locks the arm position and <code>Control</code> enables manual control again. <code>Reset</code> requests manual entry again and may move to the ready pose. <code>Stow arm and exit</code> stops held input, waits for XYZ, RPY and gripper stop requests to be accepted, then requests Folding/Home and returns home. Header navigation and in-app back navigation use the same folding request. While connected, a failed request keeps the screen open; this does not wait for physical folding completion. On disconnect, pending inputs and queued manual commands are canceled and the screen returns to the hub without automatic folding. A notice states that arm stop and stow are unconfirmed. Reconnection does not resume control: inspect the robot and explicitly start manual control again. This does not guarantee robot-side stopping or completed folding. Closing or reloading the browser tab cannot guarantee this sequence.</p><p>For translation, choose <code>FC frame</code> (the existing foot-center movement) or <code>EE frame</code>. In EE frame, +X approaches along the gripper&#39;s forward direction and −X retreats. X/Y/Z arrows follow the EE orientation; both axis dragging and the −/+ buttons use that frame. Each new hold captures the measured EE axis, maintains the current orientation reference, and requests translation at the selected fraction of the existing 0.10 m/s jog speed. Changing frames stops the current input and does not start a new movement. Rotation always uses the EE frame. The EE approach stops as a whole at the existing workspace or ground boundary; physical travel still depends on the controller and joint limits. Align the gripper yourself first: object recognition, automatic alignment, contact detection and grasping are not provided. This feature requires the updated ManiControl on the robot as well as the updated GUI; updating the GUI alone does not enable it.</p><p>The top action row also contains <code>Robot Control Mode</code> and <code>Chicken Head Mode</code>, beside <code>Reset</code>, <code>Fix</code>, <code>Control</code> and <code>Stow arm and exit</code>. Start manual control before using either mode. Both require arm control to be running and the position lock released, and stop any held EE input before sending their command. Selecting a mode does not confirm that the robot completed the change — check its status and logs.</p><p>Manual control uses the existing EE-based pitch tracking without additional automatic base-height adjustment.</p><p>In manual control, open <code>EE speed</code> beside <code>Input feedback</code> to set translation and rotation separately from 10% to 100%, or choose <code>Fine</code>, <code>Normal</code> or <code>Fast</code>. The settings apply to axis dragging and −/+ buttons and are saved on this device. Opening settings or changing speed stops the current input; closing the window does not resume movement. These percentages set the requested speed, not a measured speed or travel distance. If speed support is unavailable, update the robot software and app together. The 3D view follows the current FC heading while retaining the measured arm and EE orientation.</p><h2 id="right-card-—-observe" tabindex="-1">Right card — OBSERVE <a class="header-anchor" href="#right-card-—-observe" aria-label="Permalink to &quot;Right card — OBSERVE&quot;">​</a></h2><p>Everything about <em>what you see and hear</em> lives on the right.</p><ul><li><strong>Card</strong>: folded, it is a round glass button, and it opens and folds like the left card.</li><li><strong>Body</strong>: <ul><li><strong>Vision</strong> — the vision toggles, including <strong>P2G</strong> (Point-to-Go), which is available only while <strong>Front</strong> is the source. With P2G on, tapping a spot on the floor in the video sends the robot walking there.</li><li><strong>Scene</strong> — 3D view settings, shown only while <code>3D</code> is the source.</li><li><strong>Audio</strong> — listen to the robot, volume, and devices. A green dot means listening is on.</li><li><code>SLAM</code> — LiDAR robots only. Opens the <strong>SLAM / Nav</strong> popover and switches the view to the <code>SLAM</code> map.</li><li><strong>PTZ</strong> — robots with a PTZ camera only. Switches the view to the PTZ camera; tap again to go back to the source you were on.</li></ul></li><li><strong>Talk</strong>: the button at the bottom right, just left of the right joystick, or at the right edge in gamepad mode. Hold it to talk through the robot&#39;s speaker. It reads <strong>Talking</strong> for as long as you hold it, and it is grayed out while the speaker amplifier is off.</li><li><strong>Sounds · Capture</strong>: the two buttons just left of <code>Talk</code>. <code>Sounds</code> picks a sound and plays it on a loop on the robot. <code>Capture</code> asks whether you want a <code>Photo</code> or a <code>Record</code>ing; while recording, the button shows the elapsed time in red and tapping it again stops. When the screen is too narrow to fit them beside the center gauges, the two buttons stack above <code>Talk</code>. See <a href="/RBQ/nightly/manual/gui/media.html#control-home">Media</a>.</li><li><strong>Gyro</strong> and <strong>Speed HUD</strong> sit side by side at the bottom center of the video. Tap the gyro to enlarge it. You can turn both off in <strong>App settings</strong>.</li><li>In the <strong>simulator</strong> there are no side cards and the 3D view fills the screen. The robot is always walking, and the tool row at the bottom holds <code>Drive</code>, <code>Level</code> and <code>Reset</code>. Pick the view from the drop-down at the top center; progress is shown below it. See the simulator notes in <a href="./connection.html">Connection</a> for levels and views.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>With <strong>P2G</strong> on, the whole video area is a command surface — every tap on the floor moves the robot. Turn it off when you are done.</p></div><h2 id="joysticks-and-input-modes" tabindex="-1">Joysticks and input modes <a class="header-anchor" href="#joysticks-and-input-modes" aria-label="Permalink to &quot;Joysticks and input modes&quot;">​</a></h2><ul><li><strong>Without a gamepad</strong>, on touch devices and PCs, the screen shows two virtual joysticks. What the axes do depends on the current motion — see the axis tables in <a href="/RBQ/nightly/manual/gui/motion-commands.html">Motion commands</a>.</li><li><strong>With a gamepad</strong>, whether a physical pad or a Steam Deck, the virtual joysticks disappear and you drive with the pad&#39;s sticks. Fold the cards to see more of the video.</li><li><strong>One-stick mode</strong> in Settings › Gamepad swaps the left and right stick roles so you can drive one-handed.</li></ul><p><strong>Driving from the keyboard</strong> — on a PC with no gamepad, the keyboard works alongside the virtual joysticks. It works only on this screen: the same keys do nothing on the Hub or in settings.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd></td><td>Left stick — forward/back and sideways</td></tr><tr><td><kbd>Q</kbd> <kbd>E</kbd></td><td>Right stick left / right — turn left / right</td></tr><tr><td><kbd>↑</kbd> <kbd>↓</kbd> <kbd>←</kbd> <kbd>→</kbd></td><td>Right stick</td></tr></tbody></table><p>The robot moves while you hold a key and stops when you let go. The keyboard has no emergency-stop key — <strong>E-STOP is the button at the top right of the screen</strong>.</p><p>While connected, the bottom-left corner shows the current gait name as a small HUD.</p><h2 id="compact-layout" tabindex="-1">Compact layout <a class="header-anchor" href="#compact-layout" aria-label="Permalink to &quot;Compact layout&quot;">​</a></h2><p>On short screens — phones, or a window less than 500 px tall — the layout stays the same and only the pieces get smaller. The joysticks, tool buttons, and walkie-talkie tuck into the corners, and the left card takes only the space above them and scrolls. On narrow screens the cards get narrower too. Nothing is taken away.</p><p>On very small screens — less than 720 px wide, such as a small phone in landscape — the screen shows less. The tool buttons at the bottom and the buttons beside <code>Talk</code> show icons only, <code>E-STOP</code> at the top right shows only its emergency icon, and the signal bars in the transfer-rate chip and the gyro at the center shrink or go away. Everything still works the same.</p><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/nightly/manual/gui/developer-mode.html#control-home">Developer mode</a>.</p></blockquote>',53)])])}const f=n(i,[["render",d]]);export{w as __pageData,f as default};
